module cell
    #(
        // MODE[6]   : 0 = カスケードモード(旧01), 1 = ツリーモード(旧11)
        // MODE[5:0] : 論理演算の設定ビット
        parameter [6:0] MODE = 7'h00
    )
    (
        input  wire I_a,
        input  wire I_b,
        input  wire I_c,
        input  wire I_d,
        output wire O
    );

   wire mode_sel = MODE[6];
   wire [5:0] conf = MODE[5:0];

   reg node_a, node_b, node_c;

   always @* begin
       // --- Stage 1: node_a (旧 O_a) ---
       // どちらのモードでも常に I_a と I_b を使用
       node_a = (I_a & (I_b ^ conf[0])) ^ conf[1];

       if (mode_sel == 1'b0) begin
           // --- カスケードモード (旧 01) ---
           // node_a -> node_b -> node_c と直列に接続
           node_b = (node_a & (I_c    ^ conf[2])) ^ conf[3]; 
           node_c = (node_b & (I_d    ^ conf[4])) ^ conf[5]; 
       end else begin
           // --- ツリーモード (旧 11) ---
           // node_a と node_c が並行計算され、node_b で結合
           node_c = (I_c    & (I_d    ^ conf[4])) ^ conf[5]; 
           node_b = (node_a & (node_c ^ conf[2])) ^ conf[3]; 
       end
   end

   // 最終出力の選択
   // カスケードモードの終端は node_c、ツリーモードの終端は node_b
   assign O = (mode_sel == 1'b0) ? node_c : node_b;

endmodule/* Generated by Yosys 0.52 (git sha1 fee39a3284c90249e1d9684cf6944ffbbcbb8f90) */

